pair A, B, M, O, R, S;

O = (0,0);
A = (-1,7);
R = (5,-5);
B = (-4,3);
S = (0,-5);
M = (A + R)/2;

draw((-4,-2)--(4,2),red + dashed);
draw(O--M,red,Arrow(6));
draw((-5,0)--(5,0));
draw((0,-6)--(0,8));
draw(O--A,Arrow(6));
draw(O--R,Arrow(6));
draw(A--R,dashed,Arrow(6));
draw(O--B,Arrow(6));
draw(O--S,Arrow(6));
draw(B--S,dashed,Arrow(6));
